events.input:
S=$PWD/scripts/check-drift.sh; T=$(mktemp -d); 
echo "--- case: drift"; cp -r templates deploy $T/; cd $T; echo "workers = 2" >> deploy/app.conf; bash $S; echo "exit=$?"
echo "--- case: no owner"; rm ...

R=$PWD; S=$R/scripts/check-drift.sh; SP=<path>
mk(){ d=$(mktemp -d -p "$SP"); cp -r "$R/templates" "$R/deploy" "$d/"; echo "$d"; }
echo "--- drift"; cd "$(mk)"; echo "workers = 2" >> deploy/app.conf; ...

R=$PWD; S=$R/scripts/check-drift.sh; SP=<path>
mk(){ d=$(mktemp -d -p "$SP"); cp -r "$R/templates" "$R/deploy" "$d/"; mkdir "$d/scripts"; cp "$S" "$d/scripts/"; echo "$d"; }
echo "--- clean (repo)"; b...
